import { getCollection } from 'astro:content';
import Layout from '../../layouts/Layout.astro';
const books = (await getCollection('books')).sort((a, b) => a.data.title.localeCompare(b.data.title));
const tags = [...new Set(books.flatMap((b) => b.data.tags))].sort();
---
<Layout title="Books | Bookshelf">
  <h1>All books</h1>
  <div role="group" aria-label="Filter by tag" id="filter">
    <button type="button" aria-pressed="true" data-tag="">All</button>
    {tags.map((t) => <button type="button" aria-pressed="false" data-tag={t}>{t}</button>)}
  </div>
  <ul aria-label="Books" id="books">
    {books.map((b) => (
      <li data-slug={b.id} data-tags={JSON.stringify(b.data.tags)}>
        <a href={`/books/${b.id}`}>{b.data.title}</a>
        <span>{b.data.author}, {b.data.year}</span>
      </li>
    ))}
  </ul>
</Layout>
<script>
  import { getFavorites } from '../../lib/favorites';
  const items = [...document.querySelectorAll<HTMLLIElement>('#books li')];
  const buttons = [...document.querySelectorAll<HTMLButtonElement>('#filter button')];
  const favs = getFavorites();
  for (const li of items) {
    if (favs.includes(li.dataset.slug!)) {
      const s = document.createElement('span');
      s.textContent = 'Favorite';
      li.append(' ', s);
    }
  }
  for (const btn of buttons) {
    btn.addEventListener('click', () => {
      const tag = btn.dataset.tag!;
      for (const b of buttons) b.setAttribute('aria-pressed', String(b === btn));
      for (const li of items) {
        const tags: string[] = JSON.parse(li.dataset.tags!);
        li.hidden = !!tag && !tags.includes(tag);
      }
    });
  }
</script>
