import Layout from '../layouts/Layout.astro';
import { validateContact, type ContactErrors } from '../lib/contact';
export const prerender = false;

let values = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success = '';
if (Astro.request.method === 'POST') {
  const data = await Astro.request.formData();
  const get = (k: string) => String(data.get(k) ?? '');
  values = { name: get('name'), email: get('email'), message: get('message') };
  errors = validateContact(values);
  if (Object.keys(errors).length === 0) success = `Thanks, ${values.name.trim()}! Your message has been sent.`;
}
---
<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p id="success" role="status">{success}</p>
  <form method="post" action="/contact" novalidate hidden={!!success}>
    <div>
      <label for="name">Name</label>
      <input type="text" id="name" name="name" value={values.name} />
      <span data-error="name">{errors.name}</span>
    </div>
    <div>
      <label for="email">Email</label>
      <input type="email" id="email" name="email" value={values.email} />
      <span data-error="email">{errors.email}</span>
    </div>
    <div>
      <label for="message">Message</label>
      <textarea id="message" name="message">{values.message}</textarea>
      <span data-error="message">{errors.message}</span>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>
<script>
  import { validateContact } from '../lib/contact';
  const form = document.querySelector<HTMLFormElement>('form')!;
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const val = (n: string) => (form.elements.namedItem(n) as HTMLInputElement).value;
    const values = { name: val('name'), email: val('email'), message: val('message') };
    const errors = validateContact(values);
    for (const k of ['name', 'email', 'message'] as const) {
      form.querySelector(`[data-error="${k}"]`)!.textContent = errors[k] ?? '';
    }
    if (Object.keys(errors).length) return;
    const res = await fetch(form.action, { method: 'POST', body: new FormData(form) });
    if (res.ok) {
      document.querySelector('#success')!.textContent = `Thanks, ${values.name.trim()}! Your message has been sent.`;
      form.hidden = true;
    }
  });
</script>
